package chihalu.customstacklimit.mixin.client;

import chihalu.customstacklimit.StackLimitConfig;
import net.minecraft.client.MinecraftClient;
import net.minecraft.item.Item;
import net.minecraft.item.ItemStack;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.Shadow;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.ModifyVariable;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfoReturnable;

import java.util.UUID;

/**
 * クライアント側でItemStackのgetMaxCount()をオーバーライド
 */
@Mixin(ItemStack.class)
public abstract class ItemStackClientMixin {

    @Shadow
    public abstract Item getItem();
    
    @Shadow
    public abstract int getMaxCount();

    @Inject(method = "getMaxCount", at = @At("HEAD"), cancellable = true)
    private void customMaxCountClient(CallbackInfoReturnable<Integer> cir) {
        UUID currentPlayer = StackLimitConfig.getCurrentPlayer();
        
        // ThreadLocalから取得できない場合、クライアントプレイヤーを使用
        if (currentPlayer == null) {
            MinecraftClient client = MinecraftClient.getInstance();
            if (client != null && client.player != null) {
                currentPlayer = client.player.getUuid();
            }
        }
        
        if (currentPlayer != null) {
            int customLimit = StackLimitConfig.getPlayerStackLimit(currentPlayer);
            cir.setReturnValue(customLimit);
        }
    }
    
    /**
     * setCount()で設定される値の上限チェックを無効化
     */
    @ModifyVariable(method = "setCount", at = @At("HEAD"), argsOnly = true)
    private int modifySetCount(int count) {
        return count;
    }
}
